// Helper
function escapeContent(s) {
  // Return a string with proper JSON escaping
  return s.replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '
')
    .replace(/\t/g, '\\t')
    .replace(/\r/g, '\\r')
    .replace(/\f/g, '\\f')
    .replace(/\b/g, '\\b');
}

function makeArticle(title, slug, category, date, description, charCount, content) {
  return {
    title: title,
    slug: slug,
    category: category,
    date: date,
    description: description,
    charCount: charCount,
    content: content
  };
}

